#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    auditSourceBoundaries
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/** Check the public repository for private research tooling and machine-specific inputs. Never rewrites citations. */
import { readFileSync, readdirSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const SKIP = new Set(['.git', 'node_modules', 'dist', 'build', '.svelte-kit', '.wiki-build', '.tools', '.build', 'temp'])
const TEXT = /\.(?:[cm]?[jt]s|svelte|json|md|txt|ya?ml|html|css)$/i
const RULES = [
  /tower-extractor|extraction-core|libil2cpp\.so|libunity\.so|global-metadata\.dat|dump\.cs/i,
  /\bIL2CPP\b|\bGhidra\b|\bCapstone\b|\bAssetsTools\b|AssetTypeArrayInfo/i,
  /\bdisassembl\w*|\bdecompil\w*|\bdisasm\w*|\bdata[- ]?min(?:e|ed|ing)\b/i,
  /\bgame binary\b|\bAPK scan\b|\bSO extract\b|\bv\d+(?:\.\d+)+-arm64\b/i,
  /\b(?:UnityPy|ScriptableObject)\b|\b(?:RVA|RVAs)\b|\boffset:\s*0x[\da-f]+/i,
  /\b(?:Main|Enemy|Projectile|CustomizeGame|ModuleManager|VaultManager|TechTreeStat|ChipManager)\.[A-Za-z_]/,
  /\b(?:FIELD_OFFSETS|WORKSHOP_OFFSETS|WORKSHOP_SPEED_OFFSETS)\b|\b[A-Za-z_]+0x[\da-f]{3,}\b/i,
  /\b(?:native|internal)\s+(?:getter|instruction|method|class)\b|\baddress order\b/i,
  /\b(?:ldr|ldrb|str|strb|fmul|fadd)\s+(?:[wxsdvq]\d|#)/i,
  /\b(?:ModuleManager|CustomizeGame)\s+(?:get_|heatLevel)|\bget_\w*\s*@\s*0x/i,
  /\bGet[A-Z][A-Za-z0-9_]*(?:\(|`)|\b(?:nativeGetter|TARGETING_METHODS)\b/,
  /\b(?:Bots?|TournamentManager|WorkshopManager|Relics)\.(?:Get|Initialize|Random|BotUpdate)\w*/,
  /\b(?:Initialize|LanguageUpdate)\s+(?:NO_STORE|HARD|base)\b/,
  /\bunityVersion["']?\s*[?:]/,
]

/** Explicit guard definitions are checks, rather than claims about how game values were obtained. */
const GUARDS = new Set(['scripts/check-source-boundaries.mjs', 'scripts/check-conventions.mjs', 'tests/scripts/source-boundaries.test.ts'])

/** Inspect every path, and text formats used by source, fixtures, docs and the site. */
export function auditSourceBoundaries(root = ROOT) {
  const problems = []
  let scanned = 0
  function walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (SKIP.has(entry.name) || entry.isSymbolicLink()) continue
      // Only the root report is generated output; tooling/coverage is SDK source.
      if (dir === root && entry.name === 'coverage') continue
      const full = path.join(dir, entry.name)
      const relative = path.relative(root, full).split(path.sep).join('/')
      if (entry.isDirectory()) { walk(full); continue }
      if (RULES.some(rule => rule.test(relative))) problems.push(`${relative}: private tooling in path`)
      if (!TEXT.test(entry.name) || GUARDS.has(relative) || /(?:package-lock|pnpm-lock)\./.test(entry.name)) continue
      scanned++
      const lines = readFileSync(full, 'utf8').split(/\r?\n/)
      lines.forEach((line, index) => {
        const assetLayout = /^(?:src\/data\/assets|src\/assets)\//.test(relative)
          && /\b(?:sourceAsset|pathId)["']?\s*[?:]/.test(line)
        if (assetLayout || RULES.some(rule => rule.test(line))) problems.push(`${relative}:${index + 1}: private tooling reference`)
      })
    }
  }
  walk(root)
  return { scanned, problems }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const { scanned, problems } = auditSourceBoundaries()
  for (const problem of problems) console.error(problem)
  console.log(`Source boundaries: ${scanned} text files checked; ${problems.length} problem(s).`)
  process.exitCode = problems.length ? 1 : 0
}
